args.content:
// cmd_hpc: homopolymer-compressed sequence.
//
// Behavior pinned down against the reference binary:
//  - No option parsing at all: argv[1] is the input file ("-" or absent =
//    stdin); any further arguments are silently ignored.
//  - Open failure: stderr "[E::stk_hpc] failed to open the input file/stream."
//    and exit code 1.
//  - Output is FASTA (quality dropped), header is the name only (comment
//    dropped), sequence is collapsed run-length style: each maximal run of
//    identical bytes becomes one byte (case-sensitive, works on any byte).
//  - No line wrapping, ever.
//  - Records with an empty sequence are not printed.
//  - The reader reproduces kseq semantics exactly (verified by probing):
//      * garbage before/between records is skipped while scanning for >/@
//      * seq lines stop at '>', '@' or '+'
//      * per logical line, one trailing '\r' is stripped -- but only when the
//        accumulated string is longer than 1 (so a "\r\n" line as the very
//        first seq content leaves a '\r' in the sequence)
//      * a FASTQ record whose accumulated quality length differs from the
//        sequence length aborts reading silently (exit 0, nothing more is
//        printed); the same happens when EOF follows the '+' line directly.
// Because the shared SeqFile reader differs in these corners, this file
// implements its own kseq-faithful reader on top of seqtk_gzopen().

#include "common.h"
#include <cctype>
#include <cstdio>
#include <string>
#include <zlib.h>

namespace {

struct KseqReader {
    gzFile fp;
    int last_char = 0; // 0 = none
    std::string name, comment, seq, qual;

    explicit KseqReader(gzFile f) : fp(f) {}

    // Append one logical line (up to '\n') to s; afterwards strip one
    // trailing '\r' if the whole accumulated string is longer than 1.
    // Returns -1 at EOF with nothing read, otherwise the new length.
    int getuntil_line(std::string& s) {
        bool gotany = false;
        int c;
        while ((c = gzgetc(fp)) >= 0) {
            gotany = true;
            if (c == '\n') break;
            s.push_back((char)c);
        }
        if (!gotany) return -1;
        if (s.size() > 1 && s.back() == '\r') s.pop_back();
        return (int)s.size();
    }

    // Returns >=0 (seq length) on a record, -1 on clean EOF, -2 on error.
    int read() {
        int c, dret = 0;
        if (last_char == 0) { // scan for the next header marker
            while ((c = gzgetc(fp)) >= 0 && c != '>' && c != '@');
            if (c < 0) return -1;
            last_char = c;
        }
        name.clear(); comment.clear(); seq.clear(); qual.clear();
        // name: up to the first isspace() byte
        bool gotany = false;
        while ((c = gzgetc(fp)) >= 0) {
            if (isspace(c)) { dret = c; break; }
            name.push_back((char)c);
            gotany = true;
        }
        if (!gotany && c < 0 && name.empty()) return -1;
        if (c < 0) dret = 0; // EOF
        if (dret != '\n') getuntil_line(comment); // read & discard comment
        // sequence
        for (;;) {
            c = gzgetc(fp);
            if (c < 0) { last_char = 0; return (int)seq.size(); }
            if (c == '>' || c == '@' || c == '+') break;
            if (c == '\n') continue; // skip empty lines
            seq.push_back((char)c);
            getuntil_line(seq);
        }
        if (c != '+') { last_char = c; return (int)seq.size(); }
        // quality: skip the rest of the '+' line
        while ((c = gzgetc(fp)) >= 0 && c != '\n');
        if (c < 0) { last_char = 0; return -2; } // no quality string
        while (getuntil_line(qual) >= 0 && qual.size() < seq.size());
        last_char = 0;
        if (seq.size() != qual.size()) return -2;
        return (int)seq.size();
    }
};

} // namespace

int cmd_hpc(int argc, char** argv) {
    gzFile fp = seqtk_gzopen(argc >= 2 ? argv[1] : nullptr);
    if (fp == nullptr) {
        fprintf(stderr, "[E::stk_hpc] failed to open the input file/stream.\n");
        return 1;
    }
    KseqReader ks(fp);
    while (ks.read() >= 0) {
        const std::string& s = ks.seq;
        if (s.empty()) continue;
        fputc('>', stdout);
        fputs(ks.name.c_str(), stdout);
        fputc('\n', stdout);
        for (size_t i = 0; i < s.size(); ++i)
            if (i == 0 || s[i] != s[i - 1])
                fputc((unsigned char)s[i], stdout);
        fputc('\n', stdout);
    }
    gzclose(fp);
    return 0;
}
